{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "MJ15, which shares the same pyrazole core and aryl substituents but has a secondary amide instead of the hydrazide, showed reduced brain distribution in mice relative to SR141716A, indicating that simple amide variants of this scaffold have poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Compound 18a, a same-core analog with a secondary amide, exhibited little to no CNS penetration with a very low brain:plasma ratio, supporting that non-hydrazide amides in this series fail to achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Compound 17a, another same-core amide analog, also showed little to no CNS penetration with a very low brain:plasma ratio, reinforcing the trend that replacing the hydrazide with a simple amide abolishes brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "AM281, a brain-permeable analog, retains the hydrazide/morpholine amide and an iodo substituent; its positive brain uptake is less transferable because the query lacks the hydrazide moiety associated with CNS penetration in this series.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a primary amide analog of the rimonabant/AM281 scaffold. In the same scaffold, non-hydrazide amide analogs (MJ15, 18a, 17a) consistently show poor or negligible brain penetration, while the only brain-permeable close analogs retain the hydrazide/morpholine amide. Because the query lacks that hydrazide and has an even more polar primary amide, it is predicted to have inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact primary amide.",
    "No transporter/efflux data for the query.",
    "The primary amide's two H-bond donors may further reduce permeability relative to tested secondary amides."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

